package mx.edu.accesoindustrial
import android.content.Intent
import android.os.Bundle
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import kotlinx.coroutines.launch
class ChecklistActivity:AppCompatActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);val layout=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(32,32,32,32)};layout.addView(TextView(this).apply{text="Check-list: ${intent.getStringExtra("machine_name")}";textSize=22f});val notes=EditText(this).apply{hint="Observaciones generales";minLines=3};val send=Button(this).apply{text="Continuar a evidencia";isEnabled=false};val checks=mutableListOf<Pair<MaintenanceChecklistItem,CheckBox>>();setContentView(ScrollView(this).apply{addView(layout)});lifecycleScope.launch{try{MaintenanceContainer.api.checklist(intent.getStringExtra("machine_id")!!).forEach{item->val box=CheckBox(this@ChecklistActivity).apply{text=item.descripcion;tag=item.id};checks+=item to box;layout.addView(box)};layout.addView(notes);layout.addView(send);send.isEnabled=true;send.setOnClickListener{if(checks.any{!it.second.isChecked}){Toast.makeText(this@ChecklistActivity,"Marca todos los puntos del checklist",Toast.LENGTH_LONG).show();return@setOnClickListener};MaintenanceDraft.machineId=intent.getStringExtra("machine_id")!!;MaintenanceDraft.machineName=intent.getStringExtra("machine_name")?:"Máquina";MaintenanceDraft.observations=notes.text.toString();MaintenanceDraft.checklist=checks.map{DraftChecklistItem(it.first.id,it.second.isChecked)};startActivity(Intent(this@ChecklistActivity,EvidenceActivity::class.java))}}catch(e:Exception){layout.addView(TextView(this@ChecklistActivity).apply{text="No se pudo cargar el check-list"})}}}}
